#define PI 3.14159265358979323846
float random (in vec2 st) { return fract(sin(dot(st.xy, vec2(12.9898,78.233)))* 43758.5453123);}
mat2 scale(in vec2 s){ return mat2(s.x,.0,.0,s.y); }
mat2 rotate2d(in float a){ return mat2(cos(a),-sin(a), sin(a),cos(a)); }
float circ(in vec2 st, in vec2 o, in float r) { return length(st-o)-r; }
float box(in vec2 st, in vec2 s){
    vec2 d = abs(st)-s;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
// Based on Morgan McGuire @morgan3d https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D of a tile
    float a = random(i),
    	b = random(i + vec2(1., 0.)),
    	c = random(i + vec2(0., 1.)),
    	d = random(i + vec2(1., 1.));
    vec2 u = f * f * (3. - 2. * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1. - u.x) +
            (d - b) * u.x * u.y;
}
#define NUM_OCTAVES 6
float fbm(in vec2 st) {
    float v = 0.0,
    a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < NUM_OCTAVES; ++i) {
        v += a * noise(st);
        st = rotate2d(0.5) * st * 2. + shift;
        a *= 0.7;
    }
    return v;
}
// ------------------------------------------------------
vec3 LIGHTBLUE = vec3(95, 116, 169)/255.;
vec3 DARKBLUE = vec3(59, 70, 66)/255.;
vec3 WHITE = vec3(244, 229, 172)/255.;
vec3 BLACK = vec3(26, 8, 4)/255.;
vec3 DARKRED = vec3(132, 32, 6)/255.;
vec3 ORANGE = vec3(225, 154, 112)/255.;
vec3 YELLOW = vec3(252, 215, 108)/255.;

vec3 drawSea(vec2 st){
    vec2 q = vec2(
        fbm(st + vec2(.1)*iTime),
        fbm(st - vec2(.2,.0)*iTime)
    );
    vec2 r = vec2(
        fbm(st + 1.*q + vec2(.0,-3.)+0.1*iTime),
        fbm(1.*st + q + vec2(8.,3.)+0.026*iTime)
    );
    float sea = fbm(st+r);

    float maskSeaSun = clamp(sin(st.x*PI*PI-1.3),0.,1.),
    maskSeaBlueEdge = clamp(smoothstep(0.27,-0.15,st.x),0.,1.),
    maskSeaRedEdge = clamp(smoothstep(0.15,.9,st.x),0.,1.),
    maskSeaNorm = clamp(1.-maskSeaSun-maskSeaBlueEdge-maskSeaRedEdge,0.,1.);

    vec3 col = vec3(0.);
    col += mix(DARKBLUE,ORANGE,sea)*maskSeaNorm;
    col += mix(mix(BLACK,DARKRED,0.75),mix(ORANGE,YELLOW,0.25),sea)*maskSeaSun;
    col += mix(BLACK,DARKBLUE,sea)*maskSeaBlueEdge;
    col += mix(BLACK,DARKRED,sea)*maskSeaRedEdge;

    col += step(.3,sea)*step(sea,.32);
    col += mix(vec3(-1.),BLACK,0.788)*step(.95,sea)*step(sea,1.);
    return col;
}

vec3 drawSky(vec2 st){
    vec2 q = vec2(
        fbm(st + vec2(.1,0.)*0.1*-iTime),
        fbm(st + vec2(.12,0.)*0.1*-iTime)
    );
    vec2 r = vec2(
        fbm(st + q + vec2(0.,-6.)+0.1*0.1*-iTime),
        fbm(vec2(0.,3.)*st + q + vec2(2.)+.5*0.1*iTime)
    );
    float colTrans = smoothstep(0.,0.25,circ(st*vec2(1.,.4),vec2(0.325,0.28),0.060));

    float moreCloudsAtTop = clamp((st.y*2.),0.,1.);
    float cloudShape = clamp(fbm(st+q)*moreCloudsAtTop,0.,1.);
    vec3 clouds = mix(WHITE,
                      mix(DARKBLUE,LIGHTBLUE,st.y+0.552)
                      ,smoothstep(0.4,0.8,cloudShape));

    vec3 harshSun = mix(DARKRED,
                        mix(ORANGE,YELLOW,st.y*2.-1.108),
                        smoothstep(0.2,0.912,cloudShape));
    float cloudShadow = smoothstep(.85,.9,cloudShape)*step(cloudShape,.95);
    //cloudShadow += smoothstep(.55,.6,cloudShape)*smoothstep(cloudShape,cloudShape+.1,.65);
    float cloudHighlight = smoothstep(.7,.75,cloudShape)*smoothstep(cloudShape,cloudShape+.1,.8);

    vec3 col = vec3(.0);
	col+= clouds*colTrans;
    col += harshSun*(1.-colTrans);
	col += (-.15*cloudShadow)*max((1.-colTrans*1.),0.);
	col += (YELLOW*.3*cloudHighlight)*max((1.-colTrans*2.),0.);
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
	vec2 R = iResolution.xy;
    vec2 st = fragCoord.xy/R.y;
    st.x -= .4;
    vec2 st3 = st * scale(vec2(.5,5.));
    vec2 st2 = st * scale(vec2(0.5,1.));

    float sunShape = circ(st,vec2(0.65,0.43),0.025);
    float maskSun = smoothstep(0.,.009,sunShape);
    float maskSky = smoothstep(.0,.01,box(fract(st),vec2(1.,0.33)));
    float maskSea = 1.-maskSky;
    maskSky = clamp(maskSky*maskSun,0.,1.);

    vec3 sun = DARKRED*(1.-smoothstep(0.,.022,sunShape))
        +mix(DARKRED,ORANGE,0.7)*(1.-smoothstep(0.,.009,sunShape));
    vec3 seaCol = drawSea(st3)*maskSea;
    vec3 skyCol = drawSky(st2)*maskSky;

    fragColor = vec4(seaCol+skyCol+sun,1.);
}
